  end if;
  if new.status = 'pending' then
    if new.requester_id is distinct from auth.uid() then
      raise exception 'friendship requester cannot be changed';
    end if;
    if new.addressee_id is distinct from old.addressee_id then
      raise exception 'friendship addressee cannot be changed';
