create or replace function public.enforce_org_document_insert()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if not public.is_org_admin(new.org_id) then
    raise exception 'only organization admins can create documents';
  end if;

  if not public.current_user_sso_verified() then
    raise exception 'SSO session required';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_org_document_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if not public.is_org_admin(new.org_id) then
    raise exception 'only organization admins can update documents';
  end if;

  if not public.current_user_sso_verified() then
    raise exception 'SSO session required';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_org_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if not public.is_org_admin(old.id) then
    raise exception 'only organization admins can update organization settings';
