create or replace function public.enforce_org_access()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if tg_table_name = 'public.org_documents' then
      if not public.is_org_admin(new.org_id) then
        raise exception 'only organization admins can create documents';
      end if;
      if not public.current_user_sso_verified() then
        raise exception 'SSO session required';
      end if;
    elsif tg_table_name = 'public.orgs' then
      if not public.is_org_admin(new.id) then
        raise exception 'only organization admins can update organization settings';
      end if;
      if not public.current_user_sso_verified() then
        raise exception 'SSO session required';
      end if;
    end if;
  elsif tg_op = 'UPDATE' then
    if tg_table_name = 'public.org_documents' then
      if not public.is_org_admin(new.org_id) then
        raise exception 'only organization admins can update documents';
      end if;
      if not public.current_user_sso_verified() then
        raise exception 'SSO session required';
      end if;
    elsif tg_table_name = 'public.orgs' then
      if not public.is_org_admin(new.id) then
        raise exception 'only organization admins can update organization settings';
      end if;
      if not public.current_user_sso_verified() then
        raise exception 'SSO session required';
      end if;
    end if;
  end if;

  return new;
end;
$$;

create trigger enforce_org_access_insert
before insert on public.org_documents for each row execute function public.enforce_org_access();
create trigger enforce_org_access_update
before update on public.org_documents for each row execute function public.enforce_org_access();
create trigger enforce_org_access_insert_orgs
before insert on public.orgs for each row execute function public.enforce_org_access();
create trigger enforce_org_access_update_orgs
before update on public.orgs for each row execute function public.enforce_org_access();
