create or replace function public.enforce_requests_immutable_columns()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'open' then
      raise exception 'new requests must have status open';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.created_by <> new.created_by
       or old.unit_id <> new.unit_id
       or old.description <> new.description then
      raise exception 'only status can be updated on a request';
    end if;

    if not public.is_building_staff((select u.building_id from public.units u where u.id = new.unit_id)) then
      raise exception 'only building staff can update a request';
    end if;

    return new;
  end if;

  return new;
end;
$$;

