create or replace function public.request_status_immutable_trigger()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'open' then
      raise exception 'new requests must have status open';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.id <> new.id
       or old.unit_id <> new.unit_id
       or old.created_by <> new.created_by
       or old.description <> new.description then
      raise exception 'only request status can be updated';
    end if;

    if not public.is_building_staff(public.unit_building_id(old.unit_id)) then
      raise exception 'only building staff can update request status';
    end if;

    return new;
  end if;

  return new;
end;
$$;

