create or replace function public.is_class_instructor(p_class_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.classes c where c.id = p_class_id and c.instructor_id = auth.uid());
$$;

create or replace function public.prevent_class_spot_modification()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.class_id is distinct from old.class_id then
    raise exception 'class_id cannot be changed';
  end if;

  if new.user_id is distinct from old.user_id then
    raise exception 'user_id cannot be changed';
  end if;

  if old.status = 'enrolled' then
    if new.status <> 'deleted' then
      raise exception 'enrolled spots cannot be updated';
    end if;
    return new;
  end if;

  if old.status = 'waitlisted' then
    if new.status = 'enrolled' then
      if public.class_enrolled_count(old.class_id) >= public.class_capacity(old.class_id) then
        raise exception 'class is full';
      end if;
    elsif new.status = 'waitlisted' then
      if new <> old then
        raise exception 'waitlisted spots cannot be updated';
      end if;
    else
      raise exception 'invalid status';
    end if;
    return new;
  end if;

  raise exception 'invalid spot status';
end;
$$;

create trigger prevent_class_spot_modification_trigger
before update on public.class_spots
for each row execute function public.prevent_class_spot_modification();

create policy "Authenticated users can view all classes"
on public.classes for select to authenticated
using (true);

create policy "Users can view their own class spots"
on public.class_spots for select to authenticated
using (user_id = auth.uid());

create policy "Instructors can view class spots in their classes"
on public.class_spots for select to authenticated
using (public.is_class_instructor(class_id));

create policy "Members can join classes"
on public.class_spots for insert to authenticated
with check (
  user_id = auth.uid()
  and status in ('enrolled', 'waitlisted')
  and (
    status = 'enrolled'
    and public.class_enrolled_count(class_id) < public.class_capacity(class_id)
    or status = 'waitlisted'
    and public.class_enrolled_count(class_id) >= public.class_capacity(class_id)
  )
);

create policy "Members can move waitlisted spots to enrolled"
on public.class_spots for update to authenticated
using (user_id = auth.uid() and status = 'waitlisted')
with check (user_id = auth.uid() and status = 'enrolled' and public.class_enrolled_count(class_id) < public.class_capacity(class_id));

create policy "Members can delete their own class spots"
on public.class_spots for delete to authenticated
using (user_id = auth.uid());

create policy "Instructors can delete class spots in their classes"
on public.class_spots for delete to authenticated
using (public.is_class_instructor(class_id));
